//! `xtask modules gen`: generates the WP-90 artifacts from `features.toml` —
//! the root crate's `[features]` section and optional module dependencies,
//! the `crates/fg-core/src/features.rs` build constants, and the
//! upstream-shaped `modules.json`. All artifacts are committed; running gen
//! twice must not change anything.

use std::path::Path;

use anyhow::{Context, Result};
use serde::Serialize;

use super::manifest::{Localized, Manifest};

const GEN_COMMENT: &str =
    "# Generated by `cargo xtask modules gen` from features.toml (WP-90); do not edit by hand.";
const LANG_TIER_TODO: &str = "# TODO(WP-90 step 6, WP-10): tiers only toggle the feature; trimming the embedded\n# catalogs (backend messages and fg-ui locales) is not wired yet.";
const DEP_COMMENTS: [&str; 2] = [
    "# Optional module crates: one `mod-<id>` feature per implemented module,",
    "# regenerated by `cargo xtask modules gen` from features.toml (WP-90).",
];
const MODULES_JSON_COMMENT: &str =
    "Generated by `cargo xtask modules gen` from features.toml (WP-90); do not edit by hand.";

pub fn run(root: &Path) -> Result<()> {
    let manifest = Manifest::load(&root.join("features.toml"))?;
    let implemented = super::implemented_modules(root, &manifest);

    // 1. Root Cargo.toml: optional module deps + the generated [features].
    let cargo_path = root.join("Cargo.toml");
    let current = std::fs::read_to_string(&cargo_path).context("failed to read root Cargo.toml")?;
    let rewritten = rewrite_cargo_toml(&current, &manifest, &implemented)?;
    write_if_changed(&cargo_path, &rewritten)?;

    // 2. fg-core build constants (compiled once the runtime step wires them).
    let features_rs = render_features_rs(&manifest, &implemented);
    let features_path = root.join("crates/fg-core/src/features.rs");
    write_if_changed(&features_path, &features_rs)?;

    // 3. modules.json, upstream shape ($comment, schema, groups, modules,
    //    languages, targets, presets).
    let modules_json = render_modules_json(&manifest)?;
    write_if_changed(&root.join("modules.json"), &modules_json)?;

    println!(
        "modules gen: 27 modules, {} implemented ({}); wrote root Cargo.toml features, crates/fg-core/src/features.rs, modules.json",
        implemented.len(),
        if implemented.is_empty() {
            "none".to_string()
        } else {
            implemented.join(", ")
        }
    );
    Ok(())
}

fn write_if_changed(path: &Path, content: &str) -> Result<()> {
    let changed = match std::fs::read_to_string(path) {
        Ok(current) => current != content,
        Err(_) => true,
    };
    if !changed {
        return Ok(());
    }
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("failed to create {}", parent.display()))?;
    }
    std::fs::write(path, content).with_context(|| format!("failed to write {}", path.display()))
}

/// Rewrites the gen-owned regions of the root `Cargo.toml`: the optional
/// module dependency block inside `[dependencies]` and the whole `[features]`
/// section. Everything else is preserved byte for byte.
pub fn rewrite_cargo_toml(
    content: &str,
    manifest: &Manifest,
    implemented: &[String],
) -> Result<String> {
    let optional_ids: Vec<&str> = manifest
        .optional()
        .map(|module| module.id.as_str())
        .collect();
    let mut lines: Vec<String> = content.lines().map(str::to_string).collect();

    // [dependencies]: strip previously generated lines, re-insert the
    // canonical block after the last non-empty line of the section.
    let deps_start = find_header(&lines, "[dependencies]")?;
    let deps_end = next_header(&lines, deps_start + 1);
    let kept: Vec<String> = lines[deps_start + 1..deps_end]
        .iter()
        .filter(|line| !is_generated_dep_line(line, &optional_ids))
        .cloned()
        .collect();
    let insert_at = kept
        .iter()
        .rposition(|line| !line.trim().is_empty())
        .map_or(0, |index| index + 1);
    let mut body = Vec::with_capacity(kept.len() + implemented.len() + DEP_COMMENTS.len());
    body.extend_from_slice(&kept[..insert_at]);
    body.extend(DEP_COMMENTS.iter().map(|line| line.to_string()));
    body.extend(implemented.iter().map(|id| optional_dep_line(id)));
    body.extend_from_slice(&kept[insert_at..]);
    lines.splice(deps_start + 1..deps_end, body);

    // [features]: replace the entire section with the canonical one.
    let features_start = find_header(&lines, "[features]")?;
    let features_end = next_header(&lines, features_start + 1);
    let mut section = render_features_section(manifest, implemented);
    if features_end < lines.len() {
        section.push(String::new()); // blank line before the next section header
    }
    lines.splice(features_start..features_end, section);

    let mut out = lines.join("\n");
    out.push('\n');
    Ok(out)
}

fn optional_dep_line(id: &str) -> String {
    format!("fg-{id} = {{ workspace = true, optional = true }}")
}

fn is_generated_dep_line(line: &str, optional_ids: &[&str]) -> bool {
    if DEP_COMMENTS.contains(&line) {
        return true;
    }
    let Some(rest) = line.strip_prefix("fg-") else {
        return false;
    };
    let Some(id) = rest.strip_suffix(" = { workspace = true, optional = true }") else {
        return false;
    };
    optional_ids.contains(&id)
}

/// The canonical `[features]` section: `default` covers every implemented
/// optional module plus `lang-all` (default build = full build, like the
/// upstream default), then the three language tiers and the `mod-*` switches.
fn render_features_section(manifest: &Manifest, implemented: &[String]) -> Vec<String> {
    let mut lines = vec!["[features]".to_string(), GEN_COMMENT.to_string()];
    let mut default_items: Vec<String> = implemented
        .iter()
        .map(|id| format!("\"mod-{id}\""))
        .collect();
    default_items.push("\"lang-all\"".to_string());
    lines.push(format!("default = [{}]", default_items.join(", ")));
    lines.push(LANG_TIER_TODO.to_string());
    for tier in &manifest.language {
        lines.push(format!("{} = []", tier.feature));
    }
    for id in implemented {
        lines.push(format!("mod-{id} = [\"dep:fg-{id}\"]"));
    }
    lines
}

/// `crates/fg-core/src/features.rs`: compile-time constants describing which
/// modules and locales the final build contains.
pub fn render_features_rs(manifest: &Manifest, implemented: &[String]) -> String {
    let mut out = String::new();
    let header = [
        "//! Build-time constants for the module manifest and language tiers (WP-90).",
        "//!",
        "//! Generated by `cargo xtask modules gen` from the root `features.toml`;",
        "//! do not edit by hand.",
        "//!",
        "//! TODO(WP-90 step 5): this file is not yet included by `lib.rs`. Wiring it up",
        "//! must also forward the root crate's `mod-*` / `lang-*` features to `fg-core`",
        "//! (e.g. `mod-cron = [\"dep:fg-cron\", \"fg-core/mod-cron\"]`) so the `cfg!`",
        "//! expressions below observe the final build configuration.",
        "//!",
        "//! TODO(WP-90 step 6, WP-10): the interface locale list (`fg-ui`) and the",
        "//! backend message trimming are not wired to these tiers yet.",
    ];
    for line in header {
        out.push_str(line);
        out.push('\n');
    }
    out.push_str("#![allow(dead_code)]\n\n");

    out.push_str("/// All module ids in display (catalog) order, built or not.\n");
    out.push_str("pub const CATALOG_IDS: &[&str] = &[\n");
    for module in &manifest.module {
        out.push_str(&format!("    {:?},\n", module.id));
    }
    out.push_str("];\n\n");

    out.push_str("/// Core modules: always compiled, no Cargo switch.\n");
    out.push_str(&format!(
        "pub const CORE_MODULES: &[&str] = &[{}];\n\n",
        manifest
            .core_ids()
            .iter()
            .map(|id| format!("{id:?}"))
            .collect::<Vec<_>>()
            .join(", ")
    ));

    out.push_str(
        "/// Optional module ids in display order. The root crate generates a\n\
         /// `mod-<id>` feature (and the `dep:fg-<id>` optional dependency) only\n\
         /// for the modules whose crate exists in the workspace.\n",
    );
    out.push_str(&format!(
        "pub const OPTIONAL_MODULES: &[&str] = &[{}];\n\n",
        manifest
            .optional()
            .map(|module| format!("{:?}", module.id))
            .collect::<Vec<_>>()
            .join(", ")
    ));

    out.push_str(
        "/// Whether `id` is compiled into this build: core modules always are;\n\
         /// optional modules require their `mod-<id>` feature (forwarded from the\n\
         /// root crate, see the crate TODO above).\n",
    );
    out.push_str("pub const fn built(id: &str) -> bool {\n");
    out.push_str(&format!(
        "    matches!(id, {})\n",
        manifest
            .core_ids()
            .iter()
            .map(|id| format!("{id:?}"))
            .collect::<Vec<_>>()
            .join(" | ")
    ));
    for id in implemented {
        out.push_str(&format!(
            "        || (matches!(id, {id:?}) && cfg!(feature = \"mod-{id}\"))\n"
        ));
    }
    out.push_str("}\n\n");

    out.push_str("/// All module ids compiled into this build, in display order.\n");
    out.push_str(
        "pub fn built_modules() -> Vec<&'static str> {\n    CATALOG_IDS\n        .iter()\n        .copied()\n        .filter(|id| built(id))\n        .collect()\n}\n\n",
    );

    for tier in &manifest.language {
        let name = tier_const_name(&tier.id);
        out.push_str(&format!(
            "/// Locales of the `{}` language tier ({}).\n",
            tier.id,
            tier.locales.join(", ")
        ));
        out.push_str(&format!(
            "pub const {name}: &[&str] = &[{}];\n\n",
            tier.locales
                .iter()
                .map(|l| format!("{l:?}"))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }

    out.push_str(
        "/// Locales embedded in this build, selected by the language tier feature.\n\
         /// Precedence: `lang-zh-cn`, then `lang-cjk-en`, then the default `lang-all`.\n",
    );
    out.push_str("pub const LOCALES: &[&str] = if cfg!(feature = \"lang-zh-cn\") {\n    LANG_ZH\n} else if cfg!(feature = \"lang-cjk-en\") {\n    LANG_CJK_EN\n} else {\n    LANG_ALL\n};\n");
    out
}

fn tier_const_name(id: &str) -> String {
    let mut name = String::from("LANG");
    for part in id.split(['-', '_']) {
        name.push('_');
        name.push_str(&part.to_ascii_uppercase());
    }
    name
}

// --- modules.json -----------------------------------------------------------

#[derive(Serialize)]
struct ModulesJson<'a> {
    #[serde(rename = "$comment")]
    comment: &'static str,
    schema: u8,
    groups: Vec<GroupJson<'a>>,
    modules: Vec<ModuleJson<'a>>,
    languages: Vec<LanguageJson<'a>>,
    targets: Vec<&'a str>,
    presets: Vec<PresetJson<'a>>,
}

#[derive(Serialize)]
struct LocalizedJson<'a> {
    #[serde(rename = "zh-CN")]
    zh_cn: &'a str,
    #[serde(rename = "zh-TW")]
    zh_tw: &'a str,
    en: &'a str,
}

#[derive(Serialize)]
struct GroupJson<'a> {
    id: &'a str,
    title: LocalizedJson<'a>,
}

#[derive(Serialize)]
struct ModuleJson<'a> {
    id: &'a str,
    group: &'a str,
    core: bool,
    requires: &'a [String],
    #[serde(skip_serializing_if = "Option::is_none")]
    tag: Option<&'a str>,
    #[serde(rename = "sizeKB", skip_serializing_if = "Option::is_none")]
    size_kb: Option<u32>,
    title: LocalizedJson<'a>,
    desc: LocalizedJson<'a>,
}

#[derive(Serialize)]
struct LanguageJson<'a> {
    id: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    tag: Option<&'a str>,
    locales: &'a [String],
    #[serde(rename = "sizeKB", skip_serializing_if = "Option::is_none")]
    size_kb: Option<u32>,
}

#[derive(Serialize)]
struct PresetJson<'a> {
    id: &'a str,
    modules: &'a [String],
}

fn localized(value: &Localized) -> LocalizedJson<'_> {
    LocalizedJson {
        zh_cn: &value.zh_cn,
        zh_tw: &value.zh_tw,
        en: &value.en,
    }
}

/// Renders `modules.json` with the upstream field set: `$comment`, `schema`,
/// `groups`, `modules`, `languages`, `targets`, `presets`. `baseSizeKB` is
/// added by `xtask size-baseline` (WP-90 step 8) after the first measurement.
pub fn render_modules_json(manifest: &Manifest) -> Result<String> {
    let value = ModulesJson {
        comment: MODULES_JSON_COMMENT,
        schema: 1,
        groups: manifest
            .group
            .iter()
            .map(|group| GroupJson {
                id: &group.id,
                title: localized(&group.title),
            })
            .collect(),
        modules: manifest
            .module
            .iter()
            .map(|module| ModuleJson {
                id: &module.id,
                group: &module.group,
                core: module.core,
                requires: &module.requires,
                tag: module.tag.as_deref(),
                size_kb: module.size_kb,
                title: localized(&module.title),
                desc: localized(&module.description),
            })
            .collect(),
        languages: manifest
            .language
            .iter()
            .map(|tier| LanguageJson {
                id: &tier.id,
                tag: tier.tag.as_deref(),
                locales: &tier.locales,
                size_kb: tier.size_kb,
            })
            .collect(),
        targets: manifest.target_ids().collect(),
        presets: manifest
            .preset
            .iter()
            .map(|preset| PresetJson {
                id: &preset.id,
                modules: &preset.modules,
            })
            .collect(),
    };
    let mut out = serde_json::to_string_pretty(&value).context("failed to render modules.json")?;
    out.push('\n');
    Ok(out)
}

fn find_header(lines: &[String], header: &str) -> Result<usize> {
    lines
        .iter()
        .position(|line| line.trim() == header)
        .ok_or_else(|| anyhow::anyhow!("root Cargo.toml has no {header} section"))
}

fn next_header(lines: &[String], from: usize) -> usize {
    lines[from..]
        .iter()
        .position(|line| line.trim_start().starts_with('['))
        .map_or(lines.len(), |offset| from + offset)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::modules::testing::{fixture_root, repo_manifest};

    const FIXTURE_IMPLEMENTED: [&str; 2] = ["cron", "guard"];

    fn implemented_vec() -> Vec<String> {
        FIXTURE_IMPLEMENTED
            .iter()
            .map(|id| id.to_string())
            .collect()
    }

    fn fixture_cargo_toml() -> String {
        crate::modules::testing::FIXTURE_CARGO_TOML.to_string()
    }

    #[test]
    fn gen_is_idempotent() {
        let manifest = repo_manifest();
        let implemented = implemented_vec();
        let once = rewrite_cargo_toml(&fixture_cargo_toml(), &manifest, &implemented).unwrap();
        let twice = rewrite_cargo_toml(&once, &manifest, &implemented).unwrap();
        assert_eq!(once, twice);
    }

    #[test]
    fn gen_normalizes_manual_features_and_stale_deps() {
        let manifest = repo_manifest();
        let implemented = implemented_vec();
        let rewritten = rewrite_cargo_toml(&fixture_cargo_toml(), &manifest, &implemented).unwrap();
        // Manual preset lines are preserved semantically, in generated order.
        assert!(rewritten.contains("fg-cron = { workspace = true, optional = true }"));
        assert!(rewritten.contains("fg-guard = { workspace = true, optional = true }"));
        assert!(rewritten.contains("mod-cron = [\"dep:fg-cron\"]"));
        assert!(rewritten.contains("mod-guard = [\"dep:fg-guard\"]"));
        assert!(rewritten.contains("default = [\"mod-cron\", \"mod-guard\", \"lang-all\"]"));
        assert!(rewritten.contains("lang-all = []"));
        assert!(rewritten.contains("lang-cjk-en = []"));
        assert!(rewritten.contains("lang-zh-cn = []"));
        // Sections outside the gen-owned regions survive untouched.
        assert!(rewritten.contains("anyhow.workspace = true"));
        assert!(rewritten.contains("name = \"fgate\""));
        // Stale generated lines for other optional modules would be dropped.
        let stale = fixture_cargo_toml().replace(
            "fg-guard = { workspace = true, optional = true }",
            "fg-ddns = { workspace = true, optional = true }",
        );
        let rewritten = rewrite_cargo_toml(&stale, &manifest, &implemented).unwrap();
        assert!(!rewritten.contains("fg-ddns = { workspace = true, optional = true }"));
        assert!(rewritten.contains("fg-guard = { workspace = true, optional = true }"));
    }

    #[test]
    fn gen_features_rs_lists_constants_and_feature_gates() {
        let manifest = repo_manifest();
        let implemented = implemented_vec();
        let text = render_features_rs(&manifest, &implemented);
        assert!(text.contains("pub const CATALOG_IDS: &[&str]"));
        let catalog_entries = text
            .lines()
            .filter(|line| line.starts_with("    \""))
            .count();
        assert_eq!(catalog_entries, 27, "CATALOG_IDS lists every module");
        assert!(text.contains("matches!(id, \"portforward\" | \"ssl\" | \"webservice\")"));
        assert!(text.contains("cfg!(feature = \"mod-cron\")"));
        assert!(text.contains("cfg!(feature = \"mod-guard\")"));
        assert!(!text.contains("cfg!(feature = \"mod-ddns\")"));
        assert!(text.contains("pub const LANG_ALL"));
        assert!(text.contains("pub const LOCALES: &[&str]"));
        // Planned modules stay in the catalog constant but have no cfg gate.
        assert!(text.contains("\"protoroute\","));
    }

    #[test]
    fn gen_modules_json_matches_upstream_layout() {
        let manifest = repo_manifest();
        let text = render_modules_json(&manifest).unwrap();
        let value: serde_json::Value = serde_json::from_str(&text).unwrap();
        let object = value.as_object().unwrap();
        assert_eq!(value["schema"], 1);
        // serde_json maps sort keys alphabetically when parsed back, so the
        // key set is compared via the map and the upstream order via the
        // rendered text (the serializing struct fixes the order).
        for key in [
            "$comment",
            "schema",
            "groups",
            "modules",
            "languages",
            "targets",
            "presets",
        ] {
            assert!(object.contains_key(key), "missing key {key}");
        }
        let rendered_keys: Vec<String> = text
            .lines()
            .filter(|line| line.starts_with("  \""))
            .take(7)
            .map(|line| line.trim().split(':').next().unwrap().to_string())
            .collect();
        assert_eq!(
            rendered_keys,
            [
                "\"$comment\"",
                "\"schema\"",
                "\"groups\"",
                "\"modules\"",
                "\"languages\"",
                "\"targets\"",
                "\"presets\""
            ],
            "top-level key order must match the upstream manifest"
        );
        assert_eq!(value["modules"].as_array().unwrap().len(), 27);
        let waf = value["modules"]
            .as_array()
            .unwrap()
            .iter()
            .find(|module| module["id"] == "waf")
            .unwrap();
        assert_eq!(waf["tag"], "no_waf");
        assert_eq!(waf["sizeKB"], 7296);
        assert_eq!(waf["title"]["zh-CN"], "WAF 防火墙");
        assert_eq!(
            waf["desc"]["en"],
            "Web application firewall based on OWASP CRS"
        );
        let ssl = value["modules"]
            .as_array()
            .unwrap()
            .iter()
            .find(|module| module["id"] == "ssl")
            .unwrap();
        assert!(ssl.get("tag").is_none(), "core modules carry no tag");
        assert!(ssl.get("sizeKB").is_none(), "core modules carry no sizeKB");
        let webservice = value["modules"]
            .as_array()
            .unwrap()
            .iter()
            .find(|module| module["id"] == "webservice")
            .unwrap();
        assert_eq!(webservice["requires"], serde_json::json!(["ssl", "waf"]));
        assert_eq!(value["groups"].as_array().unwrap().len(), 6);
        assert_eq!(value["groups"][0]["id"], "network");
        assert_eq!(value["groups"][0]["title"]["zh-CN"], "网络");
        assert_eq!(value["languages"].as_array().unwrap().len(), 3);
        assert!(value["languages"][0].get("tag").is_none());
        assert_eq!(
            value["languages"][0]["locales"].as_array().unwrap().len(),
            10
        );
        assert_eq!(value["languages"][1]["tag"], "lang_cjken");
        assert_eq!(value["languages"][1]["sizeKB"], 704);
        assert_eq!(value["languages"][2]["tag"], "lang_zh");
        assert_eq!(value["languages"][2]["sizeKB"], 896);
        assert_eq!(value["targets"].as_array().unwrap().len(), 19);
        assert_eq!(value["presets"].as_array().unwrap().len(), 3);
        assert_eq!(value["presets"][1]["modules"].as_array().unwrap().len(), 10);
        assert_eq!(value["presets"][2]["modules"].as_array().unwrap().len(), 20);
    }

    #[test]
    fn gen_rewrite_matches_current_repo_cargo_toml() {
        let root = crate::modules::testing::repo_root();
        let manifest = repo_manifest();
        let implemented = super::super::implemented_modules(&root, &manifest);
        let content = std::fs::read_to_string(root.join("Cargo.toml")).expect("repo Cargo.toml");
        let rewritten = rewrite_cargo_toml(&content, &manifest, &implemented).unwrap();
        assert_eq!(
            rewritten, content,
            "root Cargo.toml drifted from the generated form; run `cargo xtask modules gen`"
        );
    }

    #[test]
    fn gen_writes_artifacts_into_fixture_root() {
        let temp = tempfile::tempdir().unwrap();
        let root = fixture_root(temp.path(), &["cron", "guard"]);
        // Running gen against a consistent fixture must change nothing.
        gen_run_for_test(&root).unwrap();
        let report = crate::modules::check::check(&root).unwrap();
        assert!(report.is_ok(), "{:?}", report.problems);
    }

    fn gen_run_for_test(root: &std::path::Path) -> Result<()> {
        let manifest = Manifest::load(&root.join("features.toml"))?;
        let implemented = super::super::implemented_modules(root, &manifest);
        let cargo = root.join("Cargo.toml");
        let current = std::fs::read_to_string(&cargo).unwrap();
        write_if_changed(
            &cargo,
            &rewrite_cargo_toml(&current, &manifest, &implemented)?,
        )?;
        write_if_changed(
            &root.join("crates/fg-core/src/features.rs"),
            &render_features_rs(&manifest, &implemented),
        )?;
        write_if_changed(&root.join("modules.json"), &render_modules_json(&manifest)?)?;
        Ok(())
    }
}
